//! Cargo-driven `xinput1_3.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is xinput1_3-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6c560000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe36000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe36000000u64)),
        o => panic!("xinput1_3-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "import:hid", "import:setupapi", "import:advapi32", "import:user32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["body", "engine:wine", "import:hid", "import:setupapi", "import:advapi32", "import:user32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "engine:wine", "import:hid", "import:setupapi", "import:advapi32", "import:user32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/xinput1_3",
        "dll/win32/xinput1_3",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/symcrypt/inc",
        "vendor/symcrypt/lib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .rust_staticlib("xinput1_3-rust")
        .c_from_compile_db("xinput1_3_shims", &["dll/win32/xinput1_3/rust_cohab_stub.c"])
        .rc("dll/win32/xinput1_3/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/xinput1_3/xinput1_3.spec", "xinput1_3.dll")
        .import_lib("dll/win32/hid/hid.spec", "hid.dll", "hid")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
